SELECT  FROM ac_hot_topic
WHERE del_flag = '0' AND user_id = #{userId}
ORDER BY hot_score DESC

SELECT  FROM ac_hot_topic
WHERE del_flag = '0' AND user_id = #{userId} AND keyword_id = #{keywordId}
ORDER BY hot_score DESC

SELECT  FROM ac_hot_topic
WHERE del_flag = '0' AND user_id = #{userId}

    AND (title LIKE CONCAT('%', #{keyword}, '%') OR description LIKE CONCAT('%', #{keyword}, '%'))

AND source = #{source}
AND hot_score >= #{minScore}
AND relevance >= #{minRelevance}
ORDER BY

    relevance
    create_time
    hot_score


    ASC
    DESC
